-- E0 ONLY (sandbox): minimal app/audit/meta objects matching the definitions read
-- from dwh on 03.11.2026 (i03_auth_audit_defs.sql), so that 005 can be tested in
-- an empty PostgreSQL. Never run against dwh or a copy of it.
CREATE SCHEMA IF NOT EXISTS app;
CREATE SCHEMA IF NOT EXISTS audit;
CREATE SCHEMA IF NOT EXISTS meta;
CREATE TABLE IF NOT EXISTS meta.source_system (
  source_system_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  code varchar(50) NOT NULL, name varchar(200) NOT NULL, source_type varchar(50) NOT NULL,
  description text, is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE app.user_account (user_id bigint PRIMARY KEY, username text NOT NULL, account_level text NOT NULL, is_active boolean NOT NULL);
CREATE TABLE app.auth_session (token_hash text PRIMARY KEY, user_id bigint NOT NULL, revoked_at timestamptz, expires_at timestamptz NOT NULL);
CREATE TABLE app.permission (permission_id bigint PRIMARY KEY, permission_code text NOT NULL, is_active boolean NOT NULL, is_assignable boolean NOT NULL DEFAULT true);
CREATE TABLE app.resource (resource_id bigint PRIMARY KEY, resource_type text NOT NULL, resource_code text NOT NULL, is_active boolean NOT NULL);
CREATE TABLE app.role (role_id bigint PRIMARY KEY, is_active boolean NOT NULL);
CREATE TABLE app.user_role_history (user_id bigint, role_id bigint, valid_to timestamptz);
CREATE TABLE app.role_permission_history (role_id bigint, permission_id bigint, valid_to timestamptz);
CREATE TABLE app.role_resource_access_history (role_id bigint, resource_id bigint, valid_to timestamptz);
INSERT INTO app.user_account VALUES (1, 'admin', 'SUPERADMIN', true), (2, 'user', 'USER', true);
INSERT INTO app.permission VALUES (1, 'ADMIN_INTEGRATION_MANAGE', true, true);

CREATE FUNCTION app.has_scoped_permission(p_user_id bigint, p_permission_code text, p_resource_type text, p_resource_code text)
 RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'pg_catalog', 'app' AS $function$
    SELECT CASE
        WHEN NOT EXISTS (SELECT 1 FROM app.user_account u WHERE u.user_id = p_user_id AND u.is_active = true) THEN false
        WHEN EXISTS (SELECT 1 FROM app.user_account u WHERE u.user_id = p_user_id AND u.is_active = true
                      AND u.account_level IN ('SUPERADMIN', 'ADMIN'))
        THEN EXISTS (SELECT 1 FROM app.permission p WHERE p.permission_code = p_permission_code AND p.is_active = true)
         AND EXISTS (SELECT 1 FROM app.resource rs WHERE rs.resource_type = p_resource_type
                      AND rs.resource_code = p_resource_code AND rs.is_active = true)
        ELSE EXISTS (SELECT 1 FROM app.user_role_history ur
                JOIN app.role r ON r.role_id = ur.role_id AND r.is_active = true
                JOIN app.role_permission_history rp ON rp.role_id = r.role_id AND rp.valid_to IS NULL
                JOIN app.permission p ON p.permission_id = rp.permission_id AND p.is_active = true AND p.is_assignable = true
                JOIN app.role_resource_access_history rr ON rr.role_id = r.role_id AND rr.valid_to IS NULL
                JOIN app.resource rs ON rs.resource_id = rr.resource_id AND rs.is_active = true
                WHERE ur.user_id = p_user_id AND ur.valid_to IS NULL AND p.permission_code = p_permission_code
                  AND rs.resource_type = p_resource_type AND rs.resource_code = p_resource_code)
    END;
$function$;

CREATE FUNCTION app.integration_admin_session_user(p_token_hash text)
 RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'app', 'audit' AS $function$
DECLARE v_user_id bigint; v_username text; v_account_level text;
BEGIN
    IF p_token_hash IS NULL OR p_token_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Invalid authentication session'; END IF;
    SELECT s.user_id, u.username, u.account_level INTO v_user_id, v_username, v_account_level
      FROM app.auth_session s JOIN app.user_account u ON u.user_id = s.user_id
     WHERE s.token_hash = p_token_hash AND s.revoked_at IS NULL AND s.expires_at > clock_timestamp() AND u.is_active = true;
    IF v_user_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
    IF v_account_level NOT IN ('SUPERADMIN', 'ADMIN') THEN RAISE EXCEPTION 'Integration administration access denied'; END IF;
    IF NOT EXISTS (SELECT 1 FROM app.permission p WHERE p.permission_code = 'ADMIN_INTEGRATION_MANAGE' AND p.is_active = true) THEN
        RAISE EXCEPTION 'ADMIN_INTEGRATION_MANAGE permission is unavailable'; END IF;
    PERFORM set_config('dwh.actor_user_id', v_user_id::text, true);
    PERFORM set_config('dwh.actor_username', v_username, true);
    PERFORM set_config('dwh.security_source', 'INTEGRATION_CONTROL', true);
    RETURN v_user_id;
END;
$function$;

CREATE TABLE audit.security_event (
  security_event_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, occurred_at timestamptz NOT NULL DEFAULT now(),
  actor_user_id bigint, actor_username text, actor_account_level text, event_type text NOT NULL,
  entity_type text NOT NULL, entity_key text, action text NOT NULL, outcome text NOT NULL,
  source text NOT NULL, request_id text, details jsonb);
CREATE FUNCTION audit.current_actor_user_id() RETURNS bigint LANGUAGE sql AS $$ SELECT nullif(current_setting('dwh.actor_user_id', true), '')::bigint $$;
CREATE FUNCTION audit.current_actor_username() RETURNS text LANGUAGE sql AS $$ SELECT nullif(current_setting('dwh.actor_username', true), '') $$;
CREATE FUNCTION audit.current_actor_account_level() RETURNS text LANGUAGE sql AS $$ SELECT NULL::text $$;
CREATE FUNCTION audit.current_security_source() RETURNS text LANGUAGE sql AS $$ SELECT coalesce(nullif(current_setting('dwh.security_source', true), ''), 'DATABASE') $$;
CREATE FUNCTION audit.current_request_id() RETURNS text LANGUAGE sql AS $$ SELECT nullif(current_setting('dwh.request_id', true), '') $$;
CREATE FUNCTION audit.log_security_event(p_event_type text, p_entity_type text, p_entity_key text, p_action text, p_outcome text, p_details jsonb)
 RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'pg_catalog', 'audit' AS $function$
DECLARE v_event_id bigint;
BEGIN
    INSERT INTO audit.security_event (actor_user_id, actor_username, actor_account_level, event_type, entity_type, entity_key,
        action, outcome, source, request_id, details)
    VALUES (audit.current_actor_user_id(), audit.current_actor_username(), audit.current_actor_account_level(), p_event_type,
        p_entity_type, p_entity_key, p_action, coalesce(p_outcome, 'SUCCESS'), audit.current_security_source(),
        audit.current_request_id(), coalesce(p_details, '{}'::jsonb))
    RETURNING security_event_id INTO v_event_id;
    RETURN v_event_id;
END;
$function$;
